package org.apache.maven.scm.command;

import org.apache.maven.scm.CommandParameters;
import org.apache.maven.scm.ScmException;
import org.apache.maven.scm.ScmFileSet;
import org.apache.maven.scm.ScmResult;
import org.apache.maven.scm.provider.ScmProviderRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * @author <a href="mailto:evenisse@apache.org">Emmanuel Venisse</a>
 * @author <a href="mailto:trygvis@inamo.no">Trygve Laugst&oslash;l</a>
 * @param <T>
 *
 */
public abstract class AbstractCommand<T extends ScmResult> implements Command<T> {
    protected Logger logger = LoggerFactory.getLogger(getClass());

    protected abstract T executeCommand(
            ScmProviderRepository repository, ScmFileSet fileSet, CommandParameters parameters) throws ScmException;

    /** {@inheritDoc} */
    public final T execute(ScmProviderRepository repository, ScmFileSet fileSet, CommandParameters parameters)
            throws ScmException {
        if (repository == null) {
            throw new NullPointerException("repository cannot be null");
        }

        if (fileSet == null) {
            throw new NullPointerException("fileSet cannot be null");
        }

        try {
            return executeCommand(repository, fileSet, parameters);
        } catch (Exception ex) {
            throw new ScmException("Exception while executing SCM command.", ex);
        }
    }
}

