/**
 * @author <a href="mailto:thurner.rupert@ymono.net">thurner rupert</a>
 * @author Olivier Lamy
 */
public class HgChangeLogCommand extends AbstractChangeLogCommand {
    /**
     * {@inheritDoc}
     */
    @Override
    protected ChangeLogScmResult executeChangeLogCommand(ChangeLogScmRequest request) throws ScmException {
        final ScmVersion startVersion = request.getStartRevision();
        final ScmVersion endVersion = request.getEndRevision();
        final ScmFileSet fileSet = request.getScmFileSet();
        final String datePattern = request.getDatePattern();
        if (startVersion != null || endVersion != null) {
            final ScmProviderRepository scmProviderRepository =
                    request.getScmRepository().getProviderRepository();
            return executeChangeLogCommand(scmProviderRepository, fileSet, startVersion, endVersion, datePattern);
        }
        return executeChangeLogCommand(
                fileSet, request.getStartDate(), request.getEndDate(), datePattern, request.getLimit());
    }

    /**
     * {@inheritDoc}
     */
    protected ChangeLogScmResult executeChangeLogCommand(
            ScmProviderRepository scmProviderRepository,
            ScmFileSet fileSet,
            Date startDate,
            Date endDate,
            ScmBranch branch,
            String datePattern)
            throws ScmException {
        return executeChangeLogCommand(fileSet, startDate, endDate, datePattern, null);
    }

    private ChangeLogScmResult executeChangeLogCommand(
            ScmFileSet fileSet, Date startDate, Date endDate, String datePattern, Integer limit) throws ScmException {
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        StringBuilder dateInterval = new StringBuilder();
        // TRICK: Mercurial 1.9.3 don't accept 1970-01-01
        dateInterval.append(
                dateFormat.format(startDate == null ? new Date(1000L * 60 * 60 * 24) : startDate)); // From 2. Jan 1970
        dateInterval.append(" to ");
        dateInterval.append(dateFormat.format(endDate == null ? new Date() : endDate)); // Upto now

        List<String> cmd = new ArrayList<>();
        cmd.addAll(Arrays.asList(
                HgCommandConstants.LOG_CMD, HgCommandConstants.TEMPLATE_OPTION,
                HgCommandConstants.TEMPLATE_FORMAT, HgCommandConstants.NO_MERGES_OPTION,
                HgCommandConstants.DATE_OPTION, dateInterval.toString()));

        if (limit != null && limit > 0) {
            cmd.add(HgCommandConstants.LIMIT_OPTION);
            cmd.add(Integer.toString(limit));
        }

        HgChangeLogConsumer consumer = new HgChangeLogConsumer(datePattern);
        ScmResult result = HgUtils.execute(consumer, fileSet.getBasedir(), cmd.toArray(new String[cmd.size()]));

        List<ChangeSet> logEntries = consumer.getModifications();
        ChangeLogSet changeLogSet = new ChangeLogSet(logEntries, startDate, endDate);
        return new ChangeLogScmResult(changeLogSet, result);
    }

    @Override
    protected ChangeLogScmResult executeChangeLogCommand(
            ScmProviderRepository repository,
            ScmFileSet fileSet,
            ScmVersion startVersion,
            ScmVersion endVersion,
            String datePattern)
            throws ScmException {
        StringBuilder revisionInterval = new StringBuilder();
        if (startVersion != null) {
            revisionInterval.append(startVersion.getName());
        }
        revisionInterval.append(":");
        if (endVersion != null) {
            revisionInterval.append(endVersion.getName());
        }

        String[] cmd = new String[] {
            HgCommandConstants.LOG_CMD,
            HgCommandConstants.TEMPLATE_OPTION,
            HgCommandConstants.TEMPLATE_FORMAT,
            HgCommandConstants.NO_MERGES_OPTION,
            HgCommandConstants.REVISION_OPTION,
            revisionInterval.toString()
        };
        HgChangeLogConsumer consumer = new HgChangeLogConsumer(datePattern);
        ScmResult result = HgUtils.execute(consumer, fileSet.getBasedir(), cmd);

        List<ChangeSet> logEntries = consumer.getModifications();
        Date startDate = null;
        Date endDate = null;
        if (!logEntries.isEmpty()) {
            startDate = logEntries.get(0).getDate();
            endDate = logEntries.get(logEntries.size() - 1).getDate();
        }
        ChangeLogSet changeLogSet = new ChangeLogSet(logEntries, startDate, endDate);
        changeLogSet.setStartVersion(startVersion);
        changeLogSet.setEndVersion(endVersion);
        return new ChangeLogScmResult(changeLogSet, result);
    }
}

