public class SvnAddCommand extends AbstractAddCommand implements SvnCommand<AddScmResult> {
    /** {@inheritDoc} */
    protected AddScmResult executeAddCommand(
            ScmProviderRepository repository, ScmFileSet fileSet, String message, boolean binary) throws ScmException {
        if (fileSet.getFileList().isEmpty()) {
            throw new ScmException("You must provide at least one file/directory to add");
        }

        Commandline cl = createCommandLine(fileSet.getBasedir(), fileSet.getFileList());

        if (binary) {
            cl.createArg().setValue("--config-option");
            cl.createArg().setValue("config:miscellany:enable-auto-props=no");
        }

        SvnAddConsumer consumer = new SvnAddConsumer();

        CommandLineUtils.StringStreamConsumer stderr = new CommandLineUtils.StringStreamConsumer();

        if (logger.isInfoEnabled()) {
            logger.info("Executing: " + SvnCommandLineUtils.cryptPassword(cl));

            if (Os.isFamily(Os.FAMILY_WINDOWS)) {
                logger.info("Working directory: " + cl.getWorkingDirectory().getAbsolutePath());
            }
        }

        int exitCode;

        try {
            exitCode = SvnCommandLineUtils.execute(cl, consumer, stderr);
        } catch (CommandLineException ex) {
            throw new ScmException("Error while executing command.", ex);
        }

        if (exitCode != 0) {
            return new AddScmResult(cl.toString(), "The svn command failed.", stderr.getOutput(), false);
        }

        return new AddScmResult(cl.toString(), consumer.getAddedFiles());
    }

    private static Commandline createCommandLine(File workingDirectory, List<File> files) throws ScmException {
        // Base command line doesn't make sense here - username/password not needed, and non-interactive is not valid

        Commandline cl = new Commandline();

        cl.setExecutable("svn");

        cl.setWorkingDirectory(workingDirectory.getAbsolutePath());

        cl.createArg().setValue("add");

        cl.createArg().setValue("--parents");

        cl.createArg().setValue("--non-recursive");

        try {
            SvnCommandLineUtils.addTarget(cl, files);
        } catch (IOException e) {
            throw new ScmException("Can't create the targets file", e);
        }

        return cl;
    }
}

